const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const questionTemplates=[
 {text:name=>`Which of these best describes ${name||'this prize'}?`,options:name=>[name||'A building set','A packet of seeds','A recipe book'],correct:0},
 {text:()=>`What is a key part of building a model?`,options:()=>['Following the instructions','Skipping every step','Using no pieces'],correct:0},
 {text:theme=>`Which theme is this competition connected to?`,options:theme=>[theme||'Building sets','Gardening','Cooking'],correct:0}
];
function autoFillQuestions(){const name=form.elements.name.value.trim(),theme=form.elements.theme.value.trim();$('#questions').innerHTML='';questionIndex=0;questionTemplates.forEach(t=>addQuestion({text:t.text(name||theme),options:t.options(theme||name),correct:t.correct}));dirty=true;$('#form-message').textContent='Questions auto-filled. Review the wording and correct answers before saving.';}
const storageKey='btw-admin-demo-v1';let demo=false,records=[],editing=null,imageData='',pending=null,dirty=false,questionIndex=0;
const form=$('#competition-form');$('#timezone').textContent='Time zone: '+Intl.DateTimeFormat().resolvedOptions().timeZone+' (your device time zone).';
const autoButton=document.createElement('button');autoButton.type='button';autoButton.className='btn outline';autoButton.textContent='Auto-fill questions';autoButton.onclick=autoFillQuestions;document.querySelector('#questions').before(autoButton);
async function request(url,options={}){const response=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to complete this request.');return data;}
async function init(){try{records=await request('/api/admin/competitions');$('#admin-mode').textContent='Administrator access verified. Drafts are private until you publish.';$('#new').disabled=false;list();}catch{const local=['localhost','127.0.0.1'].includes(location.hostname);$('#admin-mode').innerHTML='Admin sign-in is required. Your account must be authorised before you can save or publish competitions.<br><a class="btn outline" href="/auth/login">Sign in</a>'+(local?'<button id="demo" class="btn">Try local demo</button><p class="help">Demo drafts stay in this browser. Publishing in the demo updates only your local website preview.</p>':'');if(local)$('#demo').onclick=()=>{demo=true;try{records=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(records))records=[];}catch{records=[];}$('#admin-mode').textContent='LOCAL DEMO · Changes are saved in this browser only. Nothing is published to the internet.';$('#new').disabled=false;$('#publish').textContent='Publish to local preview';list();};}}
function list(){$('#admin-list').innerHTML=records.length?records.map(r=>`<article class="admin-row"><img src="${esc(r.image)}" alt=""><div class="grow"><span class="status-tag">${r.status==='published'?'Published'+(demo?' locally':''):'Draft'}</span><h3>${esc(r.name)}</h3><p>£${(r.price/100).toFixed(2)} per ticket · 200 tickets · ${esc(new Date(r.closesAt).toLocaleString('en-GB'))}</p></div><button class="btn outline" data-edit="${esc(r.id)}">Edit</button></article>`).join(''):'<div class="empty"><h2>Your next prize starts here.</h2><p>Add a competition, upload an image and prepare your questions.</p><p class="help">The three original sample prizes are separate from your new competitions.</p></div>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(records.find(r=>r.id===b.dataset.edit)));}
function openEditor(record){if(dirty&&!confirm('Discard your unsaved changes?'))return;editing=record||null;form.reset();imageData=record?.image||'';$('#questions').innerHTML='';questionIndex=0;for(const q of record?.questions||[{text:'',options:['','',''],correct:0}])addQuestion(q);for(const key of ['name','theme','description'])form.elements[key].value=record?.[key]||'';form.elements.price.value=record?(record.price/100).toFixed(2):'';if(record){const d=new Date(record.closesAt);form.elements.closesAt.value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}$('#image-preview').hidden=!imageData;$('#image-preview').src=imageData;$('#editor-title').textContent=record?'Edit competition':'Add a competition';$('#editor').hidden=false;$('#form-message').textContent='';dirty=false;$('#editor').scrollIntoView({behavior:'smooth'});}
function addQuestion(q={text:'',options:['','',''],correct:0}){if($('#questions').children.length>=10)return;const i=questionIndex++;const el=document.createElement('fieldset');el.className='question-editor';el.style.border='0';el.innerHTML=`<legend>Question</legend><label>Question text<input type="text" class="question-text" maxlength="240" required value="${esc(q.text)}"></label>${q.options.map((o,n)=>`<div class="answer-edit"><input type="radio" name="correct-${i}" value="${n}" ${q.correct===n?'checked':''} aria-label="Mark answer ${n+1} correct"><label style="flex:1">Answer ${n+1}<input type="text" class="question-option" required maxlength="120" value="${esc(o)}"></label></div>`).join('')}<button type="button" class="remove">Remove question</button>`;el.querySelector('button').onclick=()=>{if($('#questions').children.length===1){$('#form-message').textContent='Keep at least one question.';return}el.remove();dirty=true;};$('#questions').append(el);}
$('#add-question').onclick=()=>{addQuestion();dirty=true;};$('#new').onclick=()=>openEditor();$('#close-editor').onclick=()=>{if(!dirty||confirm('Discard unsaved changes?')){$('#editor').hidden=true;dirty=false;}};form.oninput=()=>dirty=true;
$('#prize-image').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>3*1024*1024){$('#form-message').textContent='Choose a PNG, JPEG or WebP under 3 MB.';e.target.value='';return;}try{const bitmap=await createImageBitmap(file);if(bitmap.width>12000||bitmap.height>12000||bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('Image dimensions are too large.');}bitmap.close();const reader=new FileReader();reader.onload=()=>{imageData=reader.result;$('#image-preview').src=imageData;$('#image-preview').hidden=false;dirty=true;$('#form-message').textContent='Image ready.';};reader.readAsDataURL(file);}catch{$('#form-message').textContent='This image could not be opened. Try another image.';}};
function collect(status){const questions=[...document.querySelectorAll('.question-editor')].map(el=>({text:el.querySelector('.question-text').value.trim(),options:[...el.querySelectorAll('.question-option')].map(x=>x.value.trim()),correct:Number(el.querySelector('input[type=radio]:checked').value)}));if(!imageData)throw Error('Upload a prize image first.');if(questions.some(q=>new Set(q.options.map(o=>o.toLowerCase())).size!==3))throw Error('Use three different choices for each question.');return {name:form.elements.name.value.trim(),theme:form.elements.theme.value.trim(),description:form.elements.description.value.trim(),price:Math.round(Number(form.elements.price.value)*100),max:200,closesAt:new Date(form.elements.closesAt.value).toISOString(),image:imageData,questions,status};}
async function save(value){if(value.status==='published'&&Date.parse(value.closesAt)<=Date.now())throw Error('Choose a future closing time before publishing.');let saved;if(demo){saved={...value,id:editing?.id||crypto.randomUUID(),revision:(editing?.revision||0)+1};const next=records.filter(r=>r.id!==saved.id).concat(saved);try{localStorage.setItem(storageKey,JSON.stringify(next));}catch{throw Error('Browser storage is full. Use a smaller image. Your current work is still in the editor.');}records=next;}else{saved=await request('/api/admin/competitions'+(editing?'/'+editing.id:''),{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...value,revision:editing?.revision})});records=records.filter(r=>r.id!==saved.id).concat(saved);}editing=saved;dirty=false;list();return saved;}
form.onsubmit=async e=>{e.preventDefault();try{const action=e.submitter?.dataset.action;pending=collect(action==='draft'?'draft':'published');if(action==='draft'){await save(pending);$('#form-message').textContent='Draft saved'+(demo?' in this browser.':'.');}else{$('#competition-preview').innerHTML=`<img src="${esc(pending.image)}" alt="${esc(pending.name)}"><span class="eyebrow">${esc(pending.theme)}</span><h2>${esc(pending.name)}</h2><p>${esc(pending.description)}</p><p><strong>£${(pending.price/100).toFixed(2)} per ticket · 200 tickets</strong><br>Closes ${esc(new Date(pending.closesAt).toLocaleString('en-GB'))}<br>${pending.questions.length} question${pending.questions.length===1?'':'s'} ready</p>`;$('#publish-message').textContent=demo?'This will appear only in your local preview.':'This will make the competition visible on your website.';$('#preview-dialog').showModal();}}catch(err){$('#form-message').textContent=err.message;}};
$('#close-preview').onclick=()=>$('#preview-dialog').close();$('#publish').onclick=async()=>{const button=$('#publish');button.disabled=true;try{await save(pending);$('#preview-dialog').close();$('#form-message').textContent=demo?'Published to your local preview. Use “View website” above to see it.':'Competition published.';}catch(err){$('#publish-message').textContent=err.message;}finally{button.disabled=false;}};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});init();
